  rough = mix(rough, 0.85, washer * 0.8);
  rough = mix(rough, 0.42 + rustField * 0.4, screw);
  metal = mix(metal, 0.0, washer * 0.9);
  metal = mix(metal, 1.0 - rustField, screw);
  ao -= (washer - screw) * 0.35;
